create table if not exists team_goals (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, user_id uuid references users(id) on delete set null, name text not null, category text, period_start date, period_end date, target numeric(14,2) default 0, current_value numeric(14,2) default 0, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists absences (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, user_id uuid references users(id) on delete cascade, kind text not null, starts_on date not null, ends_on date not null, notes text, status text not null default 'approved', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists idx_team_goals_org_period on team_goals(organization_id, period_end);
create index if not exists idx_absences_org_period on absences(organization_id, starts_on, ends_on);
